const LITTLE_ANDAMAN_LOCATIONS=[{name:"Butler Bay",lat:10.58,lng:92.58,description:"Pristine 2+ km crescent beach — India's premier surfing destination with golden sand and turquoise waters."},{name:"White Surf Waterfall",lat:10.62,lng:92.52,description:"Spectacular 60m multi-tiered cascade through evergreen forest, 6.5 km from Hut Bay."},{name:"Hut Bay (Main Settlement)",lat:10.65,lng:92.48,description:"Main town and ferry port on the northeast coast — entry point with market, accommodation, and transport."},{name:"RK Bay",lat:10.55,lng:92.55,description:"Scenic bay on the east coast with rocky headlands and access to forest trails."},{name:"Jackson Creek",lat:10.7,lng:92.45,description:"Mangrove-lined creek on the north coast — saltwater crocodile habitat and birdwatching spot."},{name:"Netaji Nagar",lat:10.6,lng:92.5,description:"Village near central forest area — access point for rainforest treks and wildlife viewing."}],LITTLE_ANDAMAN_GALLERY=[{src:"../../assets/travel_beaches.png",caption:"Butler Bay — pristine crescent beach"},{src:"../../assets/travel_islands.png",caption:"Little Andaman coastline and turquoise waters"},{src:"../../assets/travel_hidden.png",caption:"White Surf Waterfall in evergreen forest"},{src:"../../assets/travel_mountains.png",caption:"Central ridge rainforest canopy"}],LITTLE_ANDAMAN_FACTS=["Little Andaman is the fourth-largest island in the Andaman archipelago at ~730 km², yet remains one of the least developed.","Butler Bay is widely considered India's best surfing beach, with consistent swells from the open Indian Ocean.","The island is a critical habitat for the dugong (sea cow) — Andaman & Nicobar's state animal — which feeds on seagrass meadows.","Asian elephants regularly swim between Little Andaman, Great Nicobar, and other islands — a rare natural phenomenon.","White Surf Waterfall drops ~60 meters in multiple tiers, creating a 'white surf' appearance that gives it its name.","Over 80% of the island is primary evergreen rainforest with high endemism — many species found nowhere else on Earth.","The island sits on the accretionary prism of the Indian-Burma plate boundary, making it geologically active with occasional tremors."];let map,currentGalleryIndex=0,factIndex=0;function initTabs(){const e=document.querySelectorAll(".little-andaman-tab-btn"),t=document.querySelectorAll(".little-andaman-tab-panel");e.forEach(a=>{a.addEventListener("click",()=>{const n=a.getAttribute("data-tab");e.forEach(e=>e.classList.remove("active")),a.classList.add("active"),t.forEach(e=>{e.classList.toggle("active",e.id==="tab-"+n)})})})}function initGallery(){const e=document.getElementById("little-andaman-gallery-grid");e&&(e.innerHTML="",LITTLE_ANDAMAN_GALLERY.forEach((t,a)=>{const n=document.createElement("figure");n.className="little-andaman-gallery-item",n.innerHTML=`\n      <img src="${t.src}" alt="${t.caption}" loading="lazy">\n      <figcaption>${t.caption}</figcaption>\n    `,n.addEventListener("click",()=>openLightbox(a)),e.appendChild(n)}))}function initLightbox(){document.querySelectorAll("[data-close-lightbox]").forEach(e=>{e.addEventListener("click",closeLightbox)});const e=document.getElementById("little-andaman-lightbox-prev"),t=document.getElementById("little-andaman-lightbox-next");e&&e.addEventListener("click",()=>showGalleryImage(currentGalleryIndex-1)),t&&t.addEventListener("click",()=>showGalleryImage(currentGalleryIndex+1)),document.addEventListener("keydown",e=>{const t=document.getElementById("little-andaman-lightbox");t&&!t.hidden&&("Escape"===e.key&&closeLightbox(),"ArrowRight"===e.key&&showGalleryImage(currentGalleryIndex+1),"ArrowLeft"===e.key&&showGalleryImage(currentGalleryIndex-1))})}function openLightbox(e){const t=document.getElementById("little-andaman-lightbox");t&&(t.hidden=!1,document.body.style.overflow="hidden",showGalleryImage(e))}function closeLightbox(){const e=document.getElementById("little-andaman-lightbox");e&&(e.hidden=!0,document.body.style.overflow="")}function showGalleryImage(e){const t=LITTLE_ANDAMAN_GALLERY.length;currentGalleryIndex=(e+t)%t;const a=LITTLE_ANDAMAN_GALLERY[currentGalleryIndex],n=document.getElementById("little-andaman-lightbox-image"),i=document.getElementById("little-andaman-lightbox-caption");n&&(n.src=a.src),n&&(n.alt=a.caption),i&&(i.textContent=a.caption)}function initFactsRotator(){const e=document.getElementById("little-andaman-fact-text"),t=document.getElementById("little-andaman-fact-dots");function a(a){factIndex=a,e.style.opacity="0",setTimeout(()=>{e.textContent=LITTLE_ANDAMAN_FACTS[factIndex],e.style.opacity="1"},200),t&&[...t.children].forEach((e,t)=>e.classList.toggle("active",t===factIndex))}e&&(t&&LITTLE_ANDAMAN_FACTS.forEach((e,n)=>{const i=document.createElement("button");i.className="little-andaman-fact-dot"+(0===n?" active":""),i.setAttribute("aria-label","Show fact "+(n+1)),i.addEventListener("click",()=>a(n)),t.appendChild(i)}),a(0),setInterval(()=>a((factIndex+1)%LITTLE_ANDAMAN_FACTS.length),6e3))}function initMap(){document.getElementById("little-andaman-map")&&"undefined"!=typeof L&&(map=L.map("little-andaman-map",{scrollWheelZoom:!1,minZoom:9}).setView([10.6,92.5],11),L.tileLayer("https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png",{attribution:"&copy; OpenStreetMap contributors &copy; CARTO",maxZoom:18}).addTo(map),LITTLE_ANDAMAN_LOCATIONS.forEach(e=>{L.circleMarker([e.lat,e.lng],{radius:8,color:"#ff9933",fillColor:"#ffb01f",fillOpacity:.85,weight:2}).addTo(map).bindPopup(`<strong>${e.name}</strong><br>${e.description}`)}))}document.addEventListener("DOMContentLoaded",()=>{initTabs(),initGallery(),initFactsRotator(),initMap(),initLightbox()});